export function edaIcon(name: string, size = 14): string {
  const p = EDA_ICONS[name] ?? EDA_ICONS.footprint;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" width="${size}" height="${size}" aria-hidden="true">${p}</svg>`;
}

